 const view=products.length?activeOnly(s.ingredients,s.recipes,new Set(products.map(p=>p.id))):{ingredients:s.ingredients,recipes:s.recipes,hiddenIngredients:0,hiddenRecipes:0};
 async function copyRecipeAllergens(r:Recipe){const p=products.find(p=>p.id===r.productId);if(!p)return;setBusy(true);setMsg('');try{const c=recipeCost(s,r,data.today);const old=(p.draft as unknown as {allergens?:string[]}).allergens||[];const res=await fetch('/api/products',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'save',id:p.id,version:p.version,product:{...p.draft,allergens:Array.from(new Set([...old,...c.allergens])),allergensChecked:false}})});const d=await res.json() as {error?:string};if(!res.ok)throw Error(d.error||'Opslaan niet bevestigd.');await load();setMsg('Receptallergenen toegevoegd aan het productconcept. Controleer ook varianten en kruiscontact vóór publicatie.')}catch(e){setMsg(e instanceof Error?e.message:'Opslaan mislukt.')}finally{setBusy(false)}}
