 useEffect(()=>{load().catch(e=>setMsg(e.message));const t=new URLSearchParams(window.location.search).get('tab');if(t&&['facturen','ingrediënten','voorraad','recepten','week'].includes(t))setTab(t)},[]);
 useEffect(()=>{const id=new URLSearchParams(window.location.search).get('product');if(id&&products.some(p=>p.id===id)){setTab('recepten');const old=data.state.recipes.find(r=>r.productId===id);setRecipe(old?structuredClone(old):{productId:id,name:products.find(p=>p.id===id)!.draft.name,yield:1,lines:[],method:'',lossPct:0,packagingCents:0,version:0,reviewed:false});}},[products]);
 async function act(body:Record<string,unknown>,success:string){setBusy(true);setMsg('');try{const r=await fetch('/api/operations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...body,version:ver.current,requestId:(()=>{const fingerprint=JSON.stringify(body);if(!pending.current||pending.current.fingerprint!==fingerprint)pending.current={fingerprint,id:makeId()};return pending.current.id})()})});const d=await r.json() as {error?:string;plan?:NonNullable<typeof plan>};if(!r.ok)throw Error(d.error||'Geen bevestiging ontvangen.');if(d.plan){setPlan(d.plan);pending.current=null}else{await load();setPlan(null);pending.current=null}setMsg(success);return true;}catch(e){setMsg(e instanceof Error?e.message:'Opslaan niet bevestigd. Ververs eerst.');return false}finally{setBusy(false)}}
 function parse(t=raw,name='Handmatig ingevoerd',supplier=''){try{const d=parseInvoice(t,name);if(supplier&&!d.invoice.supplier)d.invoice.supplier=supplier;const found:Record<string,'artikel'|'naam'>={};d.invoice.lines=d.invoice.lines.map(l=>{const m=l.kind==='product'?suggestIngredient(l,d.invoice.supplier,s.ingredients):null;if(m)found[l.id]=m.reason;return {...l,ingredientId:m?.ingredientId||''}});setMatched(found);setDrafts({});setInvoice(d.invoice);setWarnings(d.warnings);setRaw(t);setMsg('Herkenning klaar. Controleer de regels en koppel de ingrediënten.')}catch(e){setMsg(e instanceof Error?e.message:'Uitlezen mislukt.')}}
 const ingredientSelect=(value:string,onChange:(v:string)=>void)=><select aria-label="Ingrediënt" value={value} onChange={e=>onChange(e.target.value)}><option value="">Kies ingrediënt</option>{view.ingredients.map(i=><option key={i.id} value={i.id}>{i.name} · {i.unit}</option>)}</select>;
 const productSelect=(value:string,onChange:(v:string)=>void)=><select aria-label="Verkoopproduct" style={{maxWidth:'100%'}} value={value} onChange={e=>onChange(e.target.value)}><option value="">Kies verkoopproduct</option>{products.map(p=><option key={p.id} value={p.id}>{p.draft.name}</option>)}</select>;
 // A new ingredient from an unknown invoice line: only after the owner clicks "Toevoegen". Allergens stay unchecked.
 const draftFor=(l:PurchaseLine)=>drafts[l.id]||draftIngredient(l,invoice?.supplier||'',makeId());
 async function addFromLine(l:PurchaseLine){if(!invoice)return false;const ing=draftFor(l);if(!ing.name.trim())return false;const ok=await act({action:'ingredient',ingredient:ing},'Ingrediënt '+ing.name+' toegevoegd en gekoppeld. Vul later de allergenen in.');if(ok){setInvoice(v=>v&&{...v,lines:v.lines.map(x=>x.id===l.id?{...x,ingredientId:ing.id}:x)});setMatched(m=>{const n={...m};delete n[l.id];return n})}return ok}
 async function askSuggestion(){if(!recipe)return;if(recipe.lines.length&&!window.confirm('Het voorstel vervangt de ingrediënten, porties en bereiding in dit formulier. Er wordt pas iets bewaard als je zelf op Recept bewaren klikt. Doorgaan?'))return;setBusy(true);setMsg('Claude maakt een voorstel…');try{const r=await fetch('/api/recipe-suggestion',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({productId:recipe.productId,wishes:suggest.wishes})});const d=await r.json() as {error?:string;suggestion?:Suggestion};if(!r.ok||!d.suggestion)throw Error(d.error||'Geen voorstel ontvangen.');const v=d.suggestion;setRecipe({...recipe,yield:v.yield,lossPct:v.lossPct,method:v.method,lines:v.lines,reviewed:false});setSuggest({...suggest,missing:toMissing(v.missing),note:v.note});setMsg('Voorstel ingevuld. Pas aan wat nodig is en klik daarna op Recept bewaren.')}catch(e){setMsg(e instanceof Error?e.message:'Voorstel maken mislukt.')}finally{setBusy(false)}}
 const toMissing=(list:Suggestion['missing']):Missing[]=>list.map(m=>({...m,pick:matchByName(m.name,s.ingredients,m.unit)?.id||'',origin:'inkoop',price:''}));
